import os
import logging
from flask import Flask, request, jsonify
import requests
import openai

logging.basicConfig(level=logging.INFO)
app = Flask(__name__)
BING_KEY = os.environ['BING_API_KEY']
BING_ENDPOINT = os.environ.get('BING_ENDPOINT','')
OPENAI_KEY = os.environ['OPENAI_API_KEY']
OPENAI_BASE = os.environ.get('OPENAI_API_BASE','')

openai.api_key = OPENAI_KEY
openai.api_base = OPENAI_BASE

def bing_search(query, count=5):
    headers = {'Ocp-Apim-Subscription-Key': BING_KEY}
    params = {'q': query, 'count': count, 'textDecorations': True, 'textFormat': 'HTML'}
    resp = requests.get(BING_ENDPOINT, headers=headers, params=params)
    resp.raise_for_status()
    items = resp.json().get('webPages', {}).get('value', [])
    return [{'title': i['name'], 'snippet': i['snippet'], 'url': i['url']} for i in items]

def generate_answer(query, results):
    context = "\n".join([f"{r['title']}: {r['snippet']}" for r in results])
    prompt = f"Használd a következő webes találatokat a kérdés megválaszolására:\n{context}\nKérdés: {query}"
    resp = openai.ChatCompletion.create(
        model='gpt-4',
        messages=[{'role':'system','content':'Segítőkész kutató agent.'},
                  {'role':'user','content':prompt}],
        temperature=0.2
    )
    return resp.choices[0].message.content

@app.route('/')
def index():
    return app.send_static_file('index.html')

@app.route('/search', methods=['POST'])
def search():
    data = request.get_json()
    q = data.get('query','').strip()
    if not q:
        return jsonify(results=[])
    try:
        sr = bing_search(q)
        answer = generate_answer(q, sr)
        sr.insert(0, {'title':'AI Válasz','snippet':answer,'url':''})
        return jsonify(results=sr)
    except Exception as e:
        logging.exception('Hiba a keresés során')
        return jsonify(results=[{'title':'Hiba','snippet':str(e),'url':''}]),500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=int(os.environ.get('PORT',5000)), debug=False)
